/**
 * Rules for the wedding-wide photo upload link (gallery-shared-upload).
 * Kept free of Deno APIs so the same rules are unit tested in the app.
 */

/** Tokens are 32 lowercase hex characters, generated by the database. */
export function validSharedUploadToken(value: unknown): value is string {
  return typeof value === "string" && /^[0-9a-f]{32}$/.test(value);
}

export const SHARED_UPLOAD_TYPES = ["image/jpeg", "image/png", "image/webp"] as const;
/** Hard ceiling regardless of the couple's own (larger) limit. */
export const SHARED_UPLOAD_MAX_BYTES = 15 * 1024 * 1024;
/** Attempts allowed per device, per wedding, per hour. */
export const SHARED_UPLOAD_DEVICE_LIMIT = 40;
/** Uploads accepted per wedding, per hour, across everyone. */
export const SHARED_UPLOAD_WEDDING_LIMIT = 600;

/** Trims, collapses spaces and strips control characters. Returns "" when unusable. */
export function cleanText(value: unknown, max: number): string {
  if (typeof value !== "string") return "";
  return Array.from(value, (ch) => {
    const code = ch.charCodeAt(0);
    return code < 32 || code === 127 ? " " : ch;
  })
    .join("")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, max);
}

export function cleanUploaderName(value: unknown): string | null {
  const name = cleanText(value, 60);
  return name.length >= 2 ? name : null;
}

export function maxUploadBytes(coupleLimit: unknown): number {
  const n = Number(coupleLimit);
  return n > 0 ? Math.min(n, SHARED_UPLOAD_MAX_BYTES) : SHARED_UPLOAD_MAX_BYTES;
}

export type UploadWindow = "open" | "not_open" | "closed";

export function uploadWindow(
  opensAt: string | null | undefined,
  closesAt: string | null | undefined,
  now: Date = new Date(),
): UploadWindow {
  if (opensAt && now < new Date(opensAt)) return "not_open";
  if (closesAt && now > new Date(closesAt)) return "closed";
  return "open";
}

/** Checks the file's real signature rather than trusting its declared type. */
export function sniffImageType(bytes: Uint8Array): (typeof SHARED_UPLOAD_TYPES)[number] | null {
  if (bytes.length >= 3 && bytes[0] === 0xff && bytes[1] === 0xd8 && bytes[2] === 0xff) return "image/jpeg";
  if (
    bytes.length >= 8 && bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47 &&
    bytes[4] === 0x0d && bytes[5] === 0x0a && bytes[6] === 0x1a && bytes[7] === 0x0a
  ) return "image/png";
  if (
    bytes.length >= 12 && bytes[0] === 0x52 && bytes[1] === 0x49 && bytes[2] === 0x46 && bytes[3] === 0x46 &&
    bytes[8] === 0x57 && bytes[9] === 0x45 && bytes[10] === 0x42 && bytes[11] === 0x50
  ) return "image/webp";
  return null;
}
